const setTeamAccessOverride = `-- name: SetTeamAccessOverride :one
UPDATE team SET access_override_state = $2, access_override_until = $3 WHERE id = $1 RETURNING id, build_id, team_number, access_state, access_override_until, access_override_state
`

type SetTeamAccessOverrideParams struct {
	ID                  pgtype.UUID        `json:"id"`
	AccessOverrideState string             `json:"access_override_state"`
	AccessOverrideUntil pgtype.Timestamptz `json:"access_override_until"`
}

// Records a manual access override: a direction ('open'/'closed') plus the
// time it holds until, after which the access reconciler
// (internal/orchestrator/access.go) resumes the environment's own schedule. A
// null until means the override holds until changed (there is no schedule
// boundary to hand back to). Operational state, deliberately separate from the
// authored schedule, and never touched by a redeploy. Extend pushes the until
// of an 'open' override further out.
func (q *Queries) SetTeamAccessOverride(ctx context.Context, arg SetTeamAccessOverrideParams) (Team, error) {
	row := q.db.QueryRow(ctx, setTeamAccessOverride, arg.ID, arg.AccessOverrideState, arg.AccessOverrideUntil)
	var i Team
	err := row.Scan(
		&i.ID,
		&i.BuildID,
		&i.TeamNumber,
		&i.AccessState,
		&i.AccessOverrideUntil,
		&i.AccessOverrideState,
	)
	return i, err
}

const setTeamAccessState = `-- name: SetTeamAccessState :one
UPDATE team SET access_state = $2 WHERE id = $1 RETURNING id, build_id, team_number, access_state, access_override_until, access_override_state
`

type SetTeamAccessStateParams struct {
	ID          pgtype.UUID `json:"id"`
	AccessState string      `json:"access_state"`
}

// Written once the actual OpenAccess/CloseAccess builder call completes
// (see internal/runner's executeAccess), never optimistically before --
// this column is "what CloseAccess/OpenAccess actually achieved," not a
// request. Deliberately touches ONLY access_state, never the override: the
// override records the operator's/schedule's intent and is what the access
// reconciler reads to decide the desired state, so clearing it here would let
// the reconciler immediately revert what this task just achieved. A lapsed
// override is dropped by the reconciler (ClearTeamAccessOverride), not here.
func (q *Queries) SetTeamAccessState(ctx context.Context, arg SetTeamAccessStateParams) (Team, error) {
	row := q.db.QueryRow(ctx, setTeamAccessState, arg.ID, arg.AccessState)
	var i Team
	err := row.Scan(
		&i.ID,
		&i.BuildID,
		&i.TeamNumber,
		&i.AccessState,
		&i.AccessOverrideUntil,
		&i.AccessOverrideState,
	)
	return i, err
}
